class Solution: 
    def getScore(self, sentence: str) -> int:
        tokens = list(sentence.strip().split())
        total_chars = tokens.count(" ").count(" ") + len(
            tokens[1:]
            )
        score = (1 * total_chars) / len(tokens) + 1 # score == 5
        return score

